from almanak.framework.strategies import IntentStrategy
from almanak.framework.intents import Intent
class MyStrategy(IntentStrategy):
    def decide(self, market): return Intent.swap(from_token='USDC', to_token='ETH', amount_usd=500)

import { Agent, run } from '@openserv-labs/sdk'
const agent = new Agent({ systemPrompt: 'You are a helpful assistant.' })
agent.addCapability({ name: 'greet', description: 'Greet', inputSchema: z.object({ name: z.string() }), async run({ args }) { return `Hello, ${args.name}!` } })
const { stop } = await run(agent)

